import { LightningElement, api, track } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { reduceErrors } from 'c/ldsUtils';
import getPromotionInfo from '@salesforce/apex/CG_PromotionInterfaceController.getPromotionInfo';
import statusField from '@salesforce/schema/cgcloud__Promotion__c.CG_Status__c';
import phaseField from '@salesforce/schema/cgcloud__Promotion__c.cgcloud__Phase__c';

// cgcloud status values
const LOADING = 'LOADING';
const SAVING = 'SAVING';
const VALID = 'VALID';
const DISABLED = 'DISABLED';

// Custom status values
const PREPARATION = 'Preparation';
const PLANNING = 'Planning';
const INACTIVE_STATUSES = ['Rejected', 'Cancelled'];

export default class CGPromotionInterface extends LightningElement {
    /**
     * @type {string}
     */
    @api recordId;

    /**
     * @type {object}
     */
    @track promo = {};

    /**
     * @type {object[]}
     */
    @track fields = [];

    showSpinner = true;
    readOnly = true;

    get status() {
        return this.promo?.[statusField.fieldApiName];
    }

    set status(value) {
        this.promo[statusField.fieldApiName] = value;
    }

    get phase() {
        return this.promo?.[phaseField.fieldApiName];
    }

    set phase(value) {
        this.promo[phaseField.fieldApiName] = value;
    }

    get restricted() {
        return this.status && this.status !== PLANNING;
    }

    get isActiveDisabled() {
        return this.readOnly || !INACTIVE_STATUSES.includes(this.status);
    }

    /* Data Load */

    async init() {
        try {
            await this.loadPromo();
        } catch (error) {
            console.error('Error in initialization:', reduceErrors(error).join(', \r\n'), JSON.stringify(error));
            this.showToast('Error', reduceErrors(error).join(', \r\n') || 'Failed to initialize promotion component', 'error');
        }

        this.showSpinner = false;
    }

    /**
     * @param {string} title
     * @param {string} message
     * @param {string} variant
     */
    showToast(title, message, variant = 'info') {
        this.dispatchEvent(new ShowToastEvent({ title, message, variant }));
    }

    async loadPromo() {
        if (!this.recordId && !this.promo.Id) {
            return;
        }

        const promotionInfo = await getPromotionInfo({ recordId: this.recordId ?? this.promo.Id });

        if (!promotionInfo) {
            throw new Error('No promotion info returned from server');
        }

        this.fields = this.disableFields(promotionInfo.fieldConfiguration);

        const service = this.refs.tpm;

        for (const field in promotionInfo.record) {
            if (!Object.prototype.hasOwnProperty.call(promotionInfo.record, field) || this.promo[field] !== undefined) {
                continue;
            }

            service.setPromotionField(field, promotionInfo.record[field]);
        }

        service.setPromotionField('$UserTemplate', promotionInfo.userTemplate);
        service.setPromotionField('Owner', {
            Id: promotionInfo.record.OwnerId,
            $UserTemplate: promotionInfo.ownerTemplate
        });
        service.setPromotionField('tacticTemplates', this.disableTemplateFields(promotionInfo.tacticTemplates));
        service.setPromotionField('sidebarTemplates', this.disableTemplateFields(promotionInfo.sidebarTemplates));
    }

    disableTemplateFields(templates) {
        for (const template of [...templates]) {
            template.fieldConfiguration = this.disableFields(template.fieldConfiguration);
        }

        return templates;
    }

    disableFields(fields) {
        for (const field of [...fields]) {
            if (this.restricted && field.fieldName !== statusField.fieldApiName) {
                field.disabled = true;
            }
        }

        return fields;
    }

    /* Handlers */

    onPromotionChange(e) {
        this.promo = { ...e.detail.value };
    }

    onEditModeChange(e) {
        this.readOnly = !e.detail.value;

        if (!this.readOnly) {
            if (this.phase === PREPARATION) {
                this.phase = PLANNING;

                if (!this.status) {
                    this.status = PLANNING;
                }
            }

            if (this.restricted) {
                this.showToast('Warning', `Promotion is not in ${PLANNING} status. Changes will be restricted.`, 'warning');
            }
        }
    }

    async onStatusChange(e) {
        const oldValue = e.detail.oldValue;
        const value = e.detail.value;

        // Promotion finished loading
        if (oldValue === LOADING && value === VALID) {
            await this.init();
        }

        // Promotion finished saving
        if (oldValue === SAVING && value === LOADING) {
            this.fields = []; // clear fields to force reload
            this.refs.tpm.setEditMode(false);
        }
    }

    onCalculationStatusChange(e) {
        if (e.detail.oldValue === LOADING && (e.detail.value === VALID || e.detail.value === DISABLED)) {
            this.showSpinner = false;
        }
    }

    onChange(e) {
        let field = e.target.dataset.field;
        let value = e.target.value;

        if (e.target.type === 'checkbox' || e.target.type === 'toggle') {
            value = e.target.checked;
        } else if (e.target.type === 'number') {
            value = Number(e.target.value);
        }

        this.refs.tpm.setPromotionField(field, value);
    }

    onFieldChange(e) {
        const { fieldName, value } = e.detail;

        // Handle date clamping logic
        this.handleDateClamping(fieldName, value);

        this.refs.tpm.setPromotionField(fieldName, value);
    }

    /**
     * @param {string | null} field
     * @param {any} value
     */
    /**
     * @param {string | null} field
     * @param {any} value
     */
    handleDateClamping(field, value) {
        const isFrom = field === 'cgcloud__Date_From__c';
        if (!isFrom && field !== 'cgcloud__Date_Thru__c') {
            return;
        }

        const promoClampMap = {
            cgcloud__Delivery_Date_From__c: 'cgcloud__Delivery_Date_Thru__c',
            cgcloud__Placement_Date_From__c: 'cgcloud__Placement_Date_Thru__c',
            cgcloud__Order_Date_From__c: 'cgcloud__Order_Date_Thru__c',
            cgcloud__Commit_Date__c: null,
            cgcloud__Reference_Date__c: null
        };

        const tacticClampMap = {
            cgcloud__Date_From__c: 'cgcloud__Date_Thru__c',
            cgcloud__Shipment_Date_From__c: 'cgcloud__Shipment_Date_Thru__c',
            cgcloud__Instore_Date_From__c: 'cgcloud__Instore_Date_Thru__c'
        };

        // Reusable clamp engine
        const runClamp = (record, map, setFn) => {
            Object.entries(map).forEach(([f1, f2]) => {
                [f1, f2].forEach((f) => {
                    // If field exists AND (isFrom + value is greater) OR (!isFrom + value is smaller)
                    if (f && (isFrom ? record[f] < value : record[f] > value)) {
                        setFn(f, value);
                    }
                });
            });
        };

        // 1. Process Promo
        runClamp(this.promo, promoClampMap, (f, v) => this.refs.tpm.setPromotionField(f, v));

        // 2. Process Tactics
        const tactics = this.refs.tpm.getProperty('tactics') || [];
        tactics.forEach((tactic) => runClamp(tactic, tacticClampMap, (f, v) => this.refs.tpm.setTacticField(tactic.Id, f, v)));
    }
}

