public with sharing class WorkItemCreateController {
    /**
     * Get available Work Item Templates for a given project
     * @param projectId - The project ID
     * @param parentWorkItemId - Optional parent work item ID (for filtering child templates)
     */
    @AuraEnabled(Cacheable=true)
    public static List<TemplateOption> getWorkItemTemplates(Id projectId, Id parentWorkItemId) {
        List<TemplateOption> options = new List<TemplateOption>();

        try {
            // If parent work item is specified, filter by allowed child templates
            if (parentWorkItemId != null) {
                // Get parent work item's template
                List<Work_Item__c> parentItems = [
                    SELECT Work_Item_Template__c
                    FROM Work_Item__c
                    WHERE Id = :parentWorkItemId
                    WITH USER_MODE
                    LIMIT 1
                ];

                if (!parentItems.isEmpty() && parentItems[0].Work_Item_Template__c != null) {
                    Id parentTemplateId = parentItems[0].Work_Item_Template__c;

                    // Get allowed child templates for this parent template
                    List<Allowed_Child_Type__c> allowedChildren = [
                        SELECT Child_Work_Item_Template__c, Child_Work_Item_Template__r.Name, Order__c
                        FROM Allowed_Child_Type__c
                        WHERE Parent_Work_Item_Template__c = :parentTemplateId AND Child_Work_Item_Template__r.Active__c = TRUE
                        WITH USER_MODE
                        ORDER BY Order__c NULLS LAST, Child_Work_Item_Template__r.Name
                    ];

                    for (Allowed_Child_Type__c allowedChild : allowedChildren) {
                        options.add(new TemplateOption(allowedChild.Child_Work_Item_Template__c, allowedChild.Child_Work_Item_Template__r.Name, null));
                    }
                } else {
                    // Parent has no template, allow all active templates
                    return getAllActiveTemplates();
                }
            } else {
                // No parent specified, check if project has template restrictions
                return getTemplatesForProject(projectId);
            }

            return options;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in getWorkItemTemplates: ' + e.getMessage());
            throw new AuraHandledException('Error retrieving work item templates: ' + e.getMessage());
        }
    }

    /**
     * Get templates allowed for a project (based on project template configuration)
     */
    private static List<TemplateOption> getTemplatesForProject(Id projectId) {
        List<TemplateOption> options = new List<TemplateOption>();

        // Get the project's template
        List<Project__c> projects = [
            SELECT Project_Template__c
            FROM Project__c
            WHERE Id = :projectId
            WITH USER_MODE
            LIMIT 1
        ];

        // If project has a template, get allowed work item templates
        if (!projects.isEmpty() && projects[0].Project_Template__c != null) {
            Id projectTemplateId = projects[0].Project_Template__c;

            // Get allowed work item templates for this project template
            List<Project_Template_Work_Item_Type__c> allowedTypes = [
                SELECT Work_Item_Template__c, Work_Item_Template__r.Name, Default_Order__c
                FROM Project_Template_Work_Item_Type__c
                WHERE Project_Template__c = :projectTemplateId AND Work_Item_Template__r.Active__c = TRUE
                WITH USER_MODE
                ORDER BY Default_Order__c NULLS LAST, Work_Item_Template__r.Name
            ];

            for (Project_Template_Work_Item_Type__c allowedType : allowedTypes) {
                options.add(new TemplateOption(allowedType.Work_Item_Template__c, allowedType.Work_Item_Template__r.Name, null));
            }

            // If no allowed types configured, fall back to all active templates
            if (options.isEmpty()) {
                return getAllActiveTemplates();
            }
        } else {
            // No project template, return all active templates
            return getAllActiveTemplates();
        }

        return options;
    }

    /**
     * Helper method to get all active templates
     */
    private static List<TemplateOption> getAllActiveTemplates() {
        List<TemplateOption> options = new List<TemplateOption>();

        List<Work_Item_Template__c> templates = [
            SELECT Id, Name
            FROM Work_Item_Template__c
            WHERE Active__c = TRUE
            WITH USER_MODE
            ORDER BY Name
        ];

        for (Work_Item_Template__c template : templates) {
            options.add(new TemplateOption(template.Id, template.Name, null));
        }

        return options;
    }

    /**
     * Get available resources (users and contacts) for a project
     */
    @AuraEnabled
    public static List<ResourceOption> getProjectResources(Id projectId) {
        List<ResourceOption> options = new List<ResourceOption>();

        try {
            // Get resource assignments for the project
            List<Resource_Assignment__c> assignments = [
                SELECT Id, Resource_User__c, Resource_User__r.Name, Resource_Contact__c, Resource_Contact__r.Name, Resource_Classification__c
                FROM Resource_Assignment__c
                WHERE Project__c = :projectId AND (Resource_User__c != NULL OR Resource_Contact__c != NULL)
                WITH USER_MODE
                ORDER BY Resource_Name__c
            ];

            for (Resource_Assignment__c assignment : assignments) {
                String resourceId = assignment.Resource_User__c != null ? assignment.Resource_User__c : assignment.Resource_Contact__c;

                String resourceName = assignment.Resource_User__c != null ? assignment.Resource_User__r.Name : assignment.Resource_Contact__r.Name;

                options.add(new ResourceOption(resourceId, resourceName, assignment.Resource_Classification__c));
            }

            return options;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in getProjectResources: ' + e.getMessage());
            throw new AuraHandledException('Error retrieving project resources: ' + e.getMessage());
        }
    }

    /**
     * Create a new Work Item
     */
    @AuraEnabled
    public static Id createWorkItem(Object request) {
        WorkItemCreateRequest workItemCreateRequest = (WorkItemCreateRequest) JSON.deserialize(JSON.serialize(request), WorkItemCreateRequest.class);

        try {
            // Validate required fields
            if (String.isBlank(workItemCreateRequest.projectId)) {
                throw new IllegalArgumentException('Project ID is required');
            }

            if (String.isBlank(workItemCreateRequest.name)) {
                throw new IllegalArgumentException('Work Item Name is required');
            }

            // Create work item
            Work_Item__c workItem = new Work_Item__c();
            workItem.Project__c = workItemCreateRequest.projectId;
            workItem.Work_Item_Name__c = workItemCreateRequest.name;
            workItem.Summary__c = workItemCreateRequest.summary;
            workItem.Next_Steps__c = workItemCreateRequest.nextSteps;
            workItem.Start_Date__c = workItemCreateRequest.startDate;
            workItem.Due_Date__c = workItemCreateRequest.dueDate;
            workItem.Estimated_Hours__c = workItemCreateRequest.estimatedHours;
            workItem.Status__c = 'Not Started'; // Default status

            // Set template if provided
            if (String.isNotBlank(workItemCreateRequest.templateId)) {
                workItem.Work_Item_Template__c = workItemCreateRequest.templateId;
            }

            // Set parent if provided
            if (String.isNotBlank(workItemCreateRequest.parentWorkItemId)) {
                workItem.Parent_Work_Item__c = workItemCreateRequest.parentWorkItemId;
            }

            insert as user workItem;

            // Create work item assignment if owner is specified
            /*if (String.isNotBlank(workItemCreateRequest.ownerId)) {
                // Get resource assignment for this user/contact
                List<Resource_Assignment__c> resourceAssignments = [
                    SELECT Id
                    FROM Resource_Assignment__c
                    WHERE Project__c = :workItemCreateRequest.projectId
                        AND (Resource_User__c = :workItemCreateRequest.ownerId OR Resource_Contact__c = :workItemCreateRequest.ownerId)
                    WITH USER_MODE
                    LIMIT 1
                ];

                if (!resourceAssignments.isEmpty()) {
                    Work_Item_Assignment__c assignment = new Work_Item_Assignment__c();
                    assignment.Work_Item__c = workItem.Id;
                    assignment.Resource_Assignment__c = resourceAssignments[0].Id;
                    assignment.Is_Primary__c = true;
                    assignment.Role_on_Work_Item__c = 'Owner';

                    insert as user assignment;
                }
            }*/

            return workItem.Id;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error in createWorkItem: ' + e.getMessage());
            throw new AuraHandledException('Error creating work item: ' + e.getMessage());
        }
    }

    // Wrapper classes

    public class TemplateOption {
        @AuraEnabled
        public Id value { get; set; }
        @AuraEnabled
