/**
 * Gets all root-level Work Items for a Project with their children
 *
 * @param projectId The Project ID to query Work Items for
 * @param maxDepth Maximum hierarchy depth to retrieve (default 3)
 *
 * @return ProjectDataWrapper with project dates and work items
 */
@AuraEnabled(Cacheable=true)
public static ProjectDataWrapper getWorkItemsForProject(Id projectId, Integer maxDepth) {
    try {
        if (maxDepth == null || maxDepth < 1) {
            maxDepth = 3;
        }

        // Get project with full details
        Project__c project = [
            SELECT Id, Name, Status__c, Start_Date__c, End_Date__c, Project_Manager__c, Project_Manager__r.Name, Project_Template__c
            FROM Project__c
            WHERE Id = :projectId
            WITH USER_MODE
            LIMIT 1
        ];

        // Get allowed root-level templates for this project
        List<TemplateOption> allowedTemplates = getAllowedTemplatesForProject(project.Project_Template__c);

        List<Work_Item__c> rootItems = WorkItemService.getWorkItemsForProject(projectId, maxDepth);

        // Get all template IDs for batch querying allowed child templates
        Set<Id> allTemplateIds = new Set<Id>();
        for (Work_Item__c item : rootItems) {
            if (item.Work_Item_Template__c != null) {
                allTemplateIds.add(item.Work_Item_Template__c);
            }
        }

        // Batch query allowed child templates for all templates
        Map<Id, List<TemplateOption>> templateToChildTemplates = getAllowedChildTemplatesMap(allTemplateIds);

        // Convert to wrappers
        List<WorkItemWrapper> rootWrappers = new List<WorkItemWrapper>();
        for (Work_Item__c item : rootItems) {
            WorkItemWrapper wrapper = new WorkItemWrapper(item, 0);
            // Populate allowed child templates
            if (item.Work_Item_Template__c != null && templateToChildTemplates.containsKey(item.Work_Item_Template__c)) {
                wrapper.allowedChildTemplates = templateToChildTemplates.get(item.Work_Item_Template__c);
            }
            rootWrappers.add(wrapper);
        }

        // Build hierarchy if depth > 0
        if (maxDepth > 0 && !rootWrappers.isEmpty()) {
            Set<Id> rootIds = new Set<Id>();
            for (WorkItemWrapper wrapper : rootWrappers) {
                rootIds.add(wrapper.id);
            }
            buildHierarchy(rootWrappers, rootIds, 1, maxDepth, templateToChildTemplates);
        }

        return new ProjectDataWrapper(project, rootWrappers, allowedTemplates);
    } catch (Exception e) {
        System.debug(LoggingLevel.ERROR, 'Error in getWorkItemsForProject: ' + e.getMessage());
        throw new AppException('Error retrieving Work Items: ' + e.getMessage());
    }
}

/**
 * @description Get allowed root-level work item templates for a project template
 * @param projectTemplateId The Project Template ID
 * @return List of allowed template options
 */
private static List<TemplateOption> getAllowedTemplatesForProject(Id projectTemplateId) {
    List<TemplateOption> templates = new List<TemplateOption>();

    if (projectTemplateId == null) {
        // No project template, return all active templates
        for (Work_Item_Template__c template : [
            SELECT Id, Name
            FROM Work_Item_Template__c
            WHERE Active__c = TRUE
            WITH USER_MODE
            ORDER BY Name
        ]) {
            templates.add(new TemplateOption(template.Id, template.Name));
        }
    } else {
        // Get allowed work item templates for this project template
        for (Project_Template_Work_Item_Type__c allowedType : [
            SELECT Work_Item_Template__c, Work_Item_Template__r.Name
            FROM Project_Template_Work_Item_Type__c
            WHERE Project_Template__c = :projectTemplateId AND Work_Item_Template__r.Active__c = TRUE
            WITH USER_MODE
            ORDER BY Default_Order__c NULLS LAST, Work_Item_Template__r.Name
        ]) {
            templates.add(new TemplateOption(allowedType.Work_Item_Template__c, allowedType.Work_Item_Template__r.Name));
        }

        // If no allowed types configured, fall back to all active templates
        if (templates.isEmpty()) {
            for (Work_Item_Template__c template : [
                SELECT Id, Name
                FROM Work_Item_Template__c
                WHERE Active__c = TRUE
                WITH USER_MODE
                ORDER BY Name
            ]) {
                templates.add(new TemplateOption(template.Id, template.Name));
            }
        }
    }

    return templates;
}

/**
 * @description Batch query allowed child templates for multiple parent templates
 * @param templateIds Set of parent template IDs
 * @return Map of parent template ID to list of allowed child template options
 */
private static Map<Id, List<TemplateOption>> getAllowedChildTemplatesMap(Set<Id> templateIds) {
    Map<Id, List<TemplateOption>> result = new Map<Id, List<TemplateOption>>();

    if (templateIds.isEmpty()) {
        return result;
    }

    // Query all allowed child types for all templates
    for (Allowed_Child_Type__c allowedChild : [
        SELECT Parent_Work_Item_Template__c, Child_Work_Item_Template__c, Child_Work_Item_Template__r.Name
        FROM Allowed_Child_Type__c
        WHERE Parent_Work_Item_Template__c IN :templateIds AND Child_Work_Item_Template__r.Active__c = TRUE
        WITH USER_MODE
        ORDER BY Order__c NULLS LAST, Child_Work_Item_Template__r.Name
    ]) {
        if (!result.containsKey(allowedChild.Parent_Work_Item_Template__c)) {
            result.put(allowedChild.Parent_Work_Item_Template__c, new List<TemplateOption>());
        }
        result.get(allowedChild.Parent_Work_Item_Template__c).add(
            new TemplateOption(allowedChild.Child_Work_Item_Template__c, allowedChild.Child_Work_Item_Template__r.Name)
        );
    }

    return result;
}

