/**
 * DataManager - Event-based state management for CGPM projects and work items.
 *
 * Provides a centralized data layer with:
 * - Status tracking (LOADING, VALID, SAVING, ERROR)
 * - Event-driven updates (statuschange, projectchange, workitemchange)
 * - Getter/setter methods for projects and work items
 * - Module-level cache for cross-instance synchronization
 *
 * @example
 * // In parent component template:
 * <c-data-manager
 *     lwc:ref="dataManager"
 *     record-id={recordId}
 *     object-api-name={objectApiName}
 *     onstatuschange={handleStatusChange}
 *     onprojectchange={handleProjectChange}
 *     onworkitemchange={handleWorkItemChange}>
 * </c-data-manager>
 *
 * // In parent component JS:
 * handleStatusChange(e) {
 *     const { oldValue, value, error } = e.detail;
 *     if (value === 'error') console.error(error);
 * }
 *
 * // Get data:
 * const project = this.refs.dataManager.getProject();
 * const workItem = this.refs.dataManager.getWorkItem(workItemId);
 *
 * // Set data (immediate persist):
 * this.refs.dataManager.setWorkItemField(workItemId, 'Status__c', 'Complete');
 */

import { api, wire } from 'lwc';
import BaseComponent from 'c/baseComponent';

import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';
import updateWorkItem from '@salesforce/apex/WorkItemController.updateWorkItem';
import moveWorkItemApex from '@salesforce/apex/WorkItemController.moveWorkItem';
import { getFieldValue, getRecord } from 'lightning/uiRecordApi';

import WORK_ITEM_PROJECT_FIELD from '@salesforce/schema/Work_Item__c.Project__c';
import { refreshApex } from '@salesforce/apex';

/* ======================================================================================
 * STATUS CONSTANTS
 * ====================================================================================== */

/**
 * Status states for the data manager
 * @readonly
 * @enum {string}
 */
export const Status = Object.freeze({
    LOADING: 'loading',
    VALID: 'valid',
    SAVING: 'saving',
    ERROR: 'error'
});

/* ======================================================================================
 * SHARED STATE MANAGEMENT (Module Level)
 * This allows all instances of DataManager to share the same data source of truth.
 * ====================================================================================== */

/**
 * Module-level cache storing project and work item data.
 * Key: projectId or workItemId (for work item pages)
 * Value: { project: {...}, workItems: [...], statusOptions: [...] }
 */
const DATA_CACHE = {};

/**
 * Set of all active DataManager instances for broadcasting updates.
 */
const INSTANCES = new Set();

/**
 * Clears the module-level cache for test isolation.
 * Call this in beforeEach() to ensure tests don't share state.
 * @export
 */
export function clearCache() {
    Object.keys(DATA_CACHE).forEach((key) => delete DATA_CACHE[key]);
    INSTANCES.clear();
}

/**
 * Broadcast data change to all DataManager instances for a specific context.
 * @param {string} contextId - Project ID or Work Item ID
 * @param {object} data - { project, workItems, statusOptions }
 */
const broadcastDataChange = (contextId, data) => {
    // Update cache
    DATA_CACHE[contextId] = data;

    // Notify all subscribers for this context
    for (const instance of INSTANCES) {
        if (instance.effectiveContextId === contextId) {
            instance._notifyDataLoaded(data);
        }
    }
};

/* ======================================================================================
 * DATAMANAGER COMPONENT
 * ====================================================================================== */

export default class DataManager extends BaseComponent {
    @api recordId; // Project ID or Work Item ID from record page
    @api objectApiName; // Object type (cgpm__Project__c or cgpm__Work_Item__c)
    @api hierarchyDepth = 3; // Maximum hierarchy depth to load

    // Internal state
    _status = Status.LOADING;
    _error = null;
    _project = null;
    _workItems = [];
    _statusOptions = [];
    _projectId = null; // Resolved Project ID (for Work Item pages)
    _wiredResult = {}; // Store wired result for refreshing

    /* ==================================================================================
     * LIFECYCLE
     * ================================================================================== */

    connectedCallback() {
        // Register this instance to receive broadcasts
        INSTANCES.add(this);

        // Immediate check: Do we already have data in memory?
        if (this.effectiveContextId && DATA_CACHE[this.effectiveContextId]) {
            this._notifyDataLoaded(DATA_CACHE[this.effectiveContextId]);
        }
    }

    disconnectedCallback() {
        INSTANCES.delete(this);
    }

    /* ==================================================================================
     * COMPUTED PROPERTIES
     * ================================================================================== */

    get isProjectPage() {
        return this.objectApiName === 'cgpm__Project__c';
    }

    get isWorkItemPage() {
        return this.objectApiName === 'cgpm__Work_Item__c';
    }

    /**
     * The effective context ID for caching.
     * On Project page: the project ID
     * On Work Item page: the work item ID (since we're showing that item's hierarchy)
     */
    get effectiveContextId() {
        return this.recordId;
    }

    /**
     * The effective project ID for Apex queries.
     * On Project page: the recordId
     * On Work Item page: the resolved projectId from the work item's lookup
     */
    get effectiveProjectId() {
        return this.isProjectPage ? this.recordId : (this._projectId ?? undefined);
    }

    /* ==================================================================================
     * STATUS API
     * ================================================================================== */

    /**
     * Get current status
     * @returns {string} Current status (loading, valid, saving, error)
     */
    @api
    getStatus() {
        return this._status;
    }

    /**
     * Internal: Set status and fire event
     * @param {string} newStatus - New status value
     * @param {Error} [error] - Optional error object
     */
    _setStatus(newStatus, error = null) {
        const oldStatus = this._status;
        if (oldStatus === newStatus) return;

        this._status = newStatus;
        this._error = error;

        this.dispatchEvent(
            new CustomEvent('statuschange', {
                detail: {
                    oldValue: oldStatus,
                    value: newStatus,
                    error: error?.message || null
                }
            })
        );
    }

    /* ==================================================================================
     * PROJECT API
     * ================================================================================== */

    /**
     * Get project data
     * @returns {object|null} Project object or null if not loaded
     */
    @api
    getProject() {
        return this._project ? { ...this._project } : null;
    }

    /**
     * Get a specific project field
     * @param {string} field - Field name
     * @returns {*} Field value
     */
    @api
    getProjectField(field) {
        return this._project?.[field];
    }

    /**
     * Update project with partial data (immediate persist)
     * @param {object} data - Partial project data to merge
     */
    @api
    async setProject(data) {
        if (!this._project?.projectId) {
            console.error('Cannot setProject: no project loaded');
            return;
        }

        const oldProject = { ...this._project };
        const updatedProject = { ...this._project, ...data };

        try {
            this._setStatus(Status.SAVING);
            this._project = updatedProject;

            // TODO: Add Apex method to update Project if needed
            // For now, projects are typically updated via standard record forms

            this._fireProjectChange(updatedProject);
            this._setStatus(Status.VALID);
        } catch (error) {
            // Rollback on error
            this._project = oldProject;
            this._setStatus(Status.ERROR, error);
            this.showError(this.extractErrorMessage(error), 'Error Updating Project');
        }
    }

    /**
     * Set a single project field (immediate persist)
     * @param {string} field - Field name
     * @param {*} value - Field value
     */
    @api
    async setProjectField(field, value) {
        await this.setProject({ [field]: value });
    }

    /* ==================================================================================
     * WORK ITEMS API
     * ================================================================================== */

    /**
     * Get all work items (hierarchical)
     * @param {string} [parentId] - Optional parent ID. If omitted, returns all root items.
     *                              If project ID, returns full hierarchy.
     *                              If work item ID, returns that item's children.
     * @returns {Array} Array of work item wrappers
     */
    @api
    getWorkItems(parentId) {
        if (!parentId) {
            // Return all root-level work items
            return JSON.parse(JSON.stringify(this._workItems));
        }

        // Find specific parent and return its children
        const findChildren = (items, targetId) => {
            for (const item of items) {
                if (item.id === targetId) {
                    return item.children ? JSON.parse(JSON.stringify(item.children)) : [];
                }
                if (item.children?.length) {
                    const found = findChildren(item.children, targetId);
                    if (found !== null) return found;
                }
            }
            return null;
        };

        const children = findChildren(this._workItems, parentId);
        return children !== null ? children : [];
    }

    /**
     * Get a specific work item by ID
     * @param {string} id - Work item ID
     * @returns {object|null} Work item wrapper or null if not found
     */
    @api
    getWorkItem(id) {
        const findItem = (items) => {
            for (const item of items) {
                if (item.id === id) {
                    return JSON.parse(JSON.stringify(item));
                }
                if (item.children?.length) {
                    const found = findItem(item.children);
                    if (found) return found;
                }
            }
            return null;
        };

        return findItem(this._workItems);
    }

    /**
     * Get a specific work item field
     * @param {string} id - Work item ID
     * @param {string} field - Field name
     * @returns {*} Field value or undefined
     */
    @api
    getWorkItemField(id, field) {
        const item = this.getWorkItem(id);
        return item?.[field];
    }

    /**
     * Update a work item with partial data (immediate persist)
     * @param {string} id - Work item ID
     * @param {object} data - Partial work item data to merge
     */
    @api
    async setWorkItem(id, data) {
        const item = this.getWorkItem(id);
        if (!item) {
            console.error('Cannot setWorkItem: work item not found', id);
            return;
        }

        try {
            this._setStatus(Status.SAVING);

            // Map wrapper fields to Salesforce field API names
            const fieldMap = {
                name: 'Work_Item_Name__c',
                status: 'Status__c',
                startDate: 'Start_Date__c',
                dueDate: 'Due_Date__c',
                estimatedHours: 'Estimated_Hours__c',
                actualHours: 'Actual_Hours__c',
                description: 'Summary__c',
                nextSteps: 'Next_Steps__c',
                isAtRisk: 'At_Risk__c',
                atRiskDetails: 'At_Risk_Details__c',
                isBlocked: 'Blocked__c',
                blockedDetails: 'Blocked_Details__c',
                blockerWorkItemId: 'Blocker_Work_Item__c'
            };

            // Convert wrapper field names to API field names
            const apexFields = {};
            for (const [key, value] of Object.entries(data)) {
                const apiName = fieldMap[key] || key;
                apexFields[apiName] = value;
            }

            // Call Apex to persist
            await updateWorkItem({ workItemId: id, fields: apexFields });

            // Update local cache
            this._updateWorkItemInCache(id, data);

            // Fire change event
            const updatedItem = this.getWorkItem(id);
            this._fireWorkItemChange(updatedItem, id, Object.keys(data)[0]);

            this._setStatus(Status.VALID);
            this.showSuccess('Work item updated successfully');
        } catch (error) {
            this._setStatus(Status.ERROR, error);
            this.showError(this.extractErrorMessage(error), 'Error Updating Work Item');
        }
    }

    /**
     * Set a single work item field (immediate persist)
     * @param {string} id - Work item ID
     * @param {string} field - Field name
     * @param {*} value - Field value
     */
    @api
    async setWorkItemField(id, field, value) {
        await this.setWorkItem(id, { [field]: value });
    }

    /**
     * Move a work item to a new parent (reparent or reorder)
     * @param {string} draggedItemId - ID of the work item being moved
     * @param {string} targetItemId - ID of the target work item
     */
    @api
    async setWorkItemParent(draggedItemId, targetItemId) {
        try {
            this._setStatus(Status.SAVING);

            await moveWorkItemApex({ draggedItemId, targetItemId });

            this.showSuccess('Work item moved successfully');
            await this.reload();
        } catch (error) {
            this._setStatus(Status.ERROR, error);
            this.showError(this.extractErrorMessage(error), 'Error Moving Work Item');
        }
    }

    /* ==================================================================================
     * PERSISTENCE API
     * ================================================================================== */

    /**
     * Force save any pending changes
     * Note: With immediate persist, this is mainly for future batch mode support
     */
    @api
    async save() {
        // Currently all changes are immediately persisted
        // This method exists for API completeness and future batch mode
        this._setStatus(Status.VALID);
    }

    /**
     * Reload data from server
     */
    @api
    async reload() {
        try {
            this._setStatus(Status.LOADING);
            await refreshApex(this._wiredResult);
        } catch (error) {
            this._setStatus(Status.ERROR, error);
            this.showError(this.extractErrorMessage(error), 'Error Refreshing Data');
        }
    }

    /* ==================================================================================
     * WIRE ADAPTERS
     * ================================================================================== */

    // Wire to get Work Item record (only when on Work Item page) to resolve project ID
    @wire(getRecord, {
        recordId: '$recordId',
        fields: [WORK_ITEM_PROJECT_FIELD]
    })
    wiredWorkItemRecord({ data, error }) {
        if (this.isWorkItemPage) {
            if (data) {
                this._projectId = getFieldValue(data, WORK_ITEM_PROJECT_FIELD);
            } else if (error) {
                this._setStatus(Status.ERROR, error);
                this.showError(this.extractErrorMessage(error), 'Error Loading Work Item');
            }
        }
    }

    // Wire method to load Work Items for the Project (when on Project page)
    @wire(getWorkItemsForProject, {
        projectId: '$effectiveProjectId',
        maxDepth: '$hierarchyDepth'
    })
    wiredWorkItemsForProject(result) {
        if (this.isProjectPage) {
            this._wiredResult = result;
            this._handleWiredData(result, true);
        }
    }

    // Wire method to load Work Item with Children (when on Work Item page)
    @wire(getWorkItemWithChildren, {
        workItemId: '$recordId',
        maxDepth: '$hierarchyDepth'
    })
    wiredWorkItemWithChildren(result) {
        if (this.isWorkItemPage) {
            this._wiredResult = result;
            this._handleWiredData(result, false);
        }
    }

    /**
     * Handle wired data from either method
     * @param {object} result - Wire result { data, error }
     * @param {boolean} isProjectContext - True if from project wire, false if from work item wire
     */
    _handleWiredData(result, isProjectContext) {
        const { data, error } = result;

        if (error) {
            this._setStatus(Status.ERROR, error);
            this.showError(this.extractErrorMessage(error), 'Error Loading Data');
            return;
        }

        if (!data) {
            return;
        }

        let newData;

        if (isProjectContext) {
            // ProjectDataWrapper from getWorkItemsForProject
            newData = {
                project: {
                    projectId: data.projectId,
                    projectName: data.projectName,
                    projectStatus: data.projectStatus,
                    projectStartDate: data.projectStartDate,
                    projectDueDate: data.projectDueDate,
                    projectManagerId: data.projectManagerId,
                    projectManagerName: data.projectManagerName,
                    projectTemplateId: data.projectTemplateId,
                    allowedTemplates: data.allowedTemplates || []
                },
                workItems: data.workItems || [],
                statusOptions: data.statusOptions || this.defaultStatusOptions
            };
        } else {
            // WorkItemWrapper from getWorkItemWithChildren
            newData = {
                project: null, // Work item page doesn't have full project data
                workItems: [data],
                statusOptions: this.defaultStatusOptions
            };
        }

        // Deduplication: Skip if data is identical
        const contextId = this.effectiveContextId;
        const cached = DATA_CACHE[contextId];

        if (cached && JSON.stringify(cached) === JSON.stringify(newData)) {
            return;
        }

        // Broadcast to all instances
        broadcastDataChange(contextId, newData);
    }

    /* ==================================================================================
     * INTERNAL HELPERS
     * ================================================================================== */

    /**
     * Internal: Handle data loaded notification
     * @param {object} data - { project, workItems, statusOptions }
     */
    _notifyDataLoaded(data) {
        this._project = data.project;
        this._workItems = data.workItems || [];
        this._statusOptions = data.statusOptions || this.defaultStatusOptions;

        // Fire project change if we have project data
        if (data.project) {
            this._fireProjectChange(data.project);
        }

        // Fire work items change
        this.dispatchEvent(
            new CustomEvent('workitemsload', {
                detail: {
                    workItems: this._workItems,
                    statusOptions: this._statusOptions,
                    project: this._project
                }
            })
        );

        this._setStatus(Status.VALID);
    }

    /**
     * Fire project change event
     * @param {object} project - Project data
     * @param {string} [field] - Optional field that changed
     */
    _fireProjectChange(project, field = null) {
        this.dispatchEvent(
            new CustomEvent('projectchange', {
                detail: {
                    value: project,
                    field
                }
            })
        );
    }

    /**
     * Fire work item change event
     * @param {object} workItem - Work item data
     * @param {string} workItemId - Work item ID
     * @param {string} [field] - Optional field that changed
     */
    _fireWorkItemChange(workItem, workItemId, field = null) {
        this.dispatchEvent(
            new CustomEvent('workitemchange', {
                detail: {
                    value: workItem,
                    workItemId,
                    field
                }
            })
        );
    }

    /**
     * Update a work item in the local cache
     * @param {string} id - Work item ID
     * @param {object} data - Partial data to merge
     */
    _updateWorkItemInCache(id, data) {
        const updateItem = (items) => {
            for (let i = 0; i < items.length; i++) {
                if (items[i].id === id) {
                    items[i] = { ...items[i], ...data };
                    return true;
                }
                if (items[i].children?.length) {
                    if (updateItem(items[i].children)) return true;
                }
            }
            return false;
        };

        updateItem(this._workItems);

        // Update the shared cache
        const contextId = this.effectiveContextId;
        if (DATA_CACHE[contextId]) {
            DATA_CACHE[contextId].workItems = this._workItems;
        }
    }
