/**
 * Work Item Details component - displays detailed work item information.
 * Uses dataManager for data access and event-based updates.
 */

import { api, track } from 'lwc';
import BaseComponent from 'c/baseComponent';
import { Status } from 'c/dataManager';

export default class WorkItemDetails extends BaseComponent {
    @api recordId; // Project or Work Item ID
    @api objectApiName; // Object type (cgpm__Project__c or cgpm__Work_Item__c)

    @track workItems = []; // Loaded Work Items
    @track record = {}; // Currently active Work Item
    @track project = null; // Project data

    _isLoading = true;
    errorMessage = '';

    connectedCallback() {
        console.log('Details Component Init:', {
            id: this.recordId,
            obj: this.objectApiName
        });
    }

    /**
     * Handle status changes from dataManager
     */
    handleStatusChange(event) {
        const { value, error } = event.detail;

        this._isLoading = value === Status.LOADING || value === Status.SAVING;

        if (value === Status.ERROR && error) {
            this.errorMessage = error;
        } else if (value === Status.VALID) {
            this.errorMessage = '';
        }
    }

    /**
     * Handle project changes from dataManager
     */
    handleProjectChange(event) {
        const { value } = event.detail;
        this.project = value;
    }

    /**
     * Handle messages from Lightning Message Service
     */
    handleMessage(message) {
        super.handleMessage(message);

        switch (message.action) {
            case 'activateWorkItem':
                this.record = this.findWorkItem(message.workItemId) || {};
                break;

            case 'workItemUpdated':
                // Reload to get fresh data
                if (!message.keepModalOpen) {
                    this.refs.dataManager?.reload();
                }
                break;

            default:
            // Do nothing for other messages
        }
    }

    /**
     * Handle wired data from dataManager
     */
    handleWorkItemsLoad(event) {
        const { workItems, project } = event.detail;
        this.workItems = this.flattenWorkItems(workItems || []);
        this.project = project;

        // If we have a specific work item context, set it as the active record
        if (this.objectApiName === 'cgpm__Work_Item__c' && workItems?.length > 0) {
            this.record = workItems[0];
        }
    }

    /**
     * Flatten work items hierarchy for easy lookup
     */
    flattenWorkItems(items) {
        let result = [];
        for (const item of items) {
            result.push(item);
            if (item.children?.length > 0) {
                result = result.concat(this.flattenWorkItems(item.children));
            }
        }
        return result;
    }

    /**
     * Find a work item by ID in the flattened list
     */
    findWorkItem(id) {
        return this.workItems.find((item) => item.id === id);
    }

    // === Computed Properties ===

    get isLoading() {
        return this._isLoading;
    }

    get hasError() {
        return this.errorMessage && this.errorMessage.length > 0;
    }

    get hasRecord() {
        return this.record && this.record.id;
    }
}

