/**
 * @jest-environment jsdom
 *
 * Tests for dataManager component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Shared state management using module-level cache
 * - Uses wire adapters for work items
 * - Exports clearCache() and Status for external use
 * - Broadcasts data changes to all instances
 * - Provides getter/setter API for projects and work items
 * - Fires statuschange, projectchange, workitemchange events
 */
import { createElement } from 'lwc';
import DataManager, { clearCache, Status } from 'c/dataManager';
import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';
import updateWorkItem from '@salesforce/apex/WorkItemController.updateWorkItem';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemsForProject',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemWithChildren',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.updateWorkItem',
    () => ({ default: jest.fn().mockResolvedValue(undefined) }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.moveWorkItem',
    () => ({ default: jest.fn().mockResolvedValue(undefined) }),
    { virtual: true }
);

// Mock getRecord wire
jest.mock('lightning/uiRecordApi', () => ({
    getRecord: jest.fn(),
    getFieldValue: jest.fn()
}), { virtual: true });

// Mock schema field
jest.mock(
    '@salesforce/schema/Work_Item__c.Project__c',
    () => ({ fieldApiName: 'Project__c', objectApiName: 'Work_Item__c' }),
    { virtual: true }
);

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-data-manager', () => {
    // Clean up DOM, mocks, and module cache after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        clearCache();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-data-manager', {
            is: DataManager
        });
        Object.assign(element, {
            recordId: 'proj-001',
            objectApiName: 'cgpm__Project__c',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('exports', () => {
        it('exports clearCache function', () => {
            expect(typeof clearCache).toBe('function');
        });

        it('exports Status constants', () => {
            expect(Status).toBeDefined();
            expect(Status.LOADING).toBe('loading');
            expect(Status.VALID).toBe('valid');
            expect(Status.SAVING).toBe('saving');
            expect(Status.ERROR).toBe('error');
        });

        it('Status object is frozen', () => {
            expect(Object.isFrozen(Status)).toBe(true);
        });
    });

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({ recordId: 'proj-002' });
            expect(element.recordId).toBe('proj-002');
        });

        it('accepts objectApiName property', () => {
            const element = createComponent({ objectApiName: 'cgpm__Work_Item__c' });
            expect(element.objectApiName).toBe('cgpm__Work_Item__c');
        });

        it('accepts hierarchyDepth property with default of 3', () => {
            const element = createComponent();
            expect(element.hierarchyDepth).toBe(3);
        });
    });

    describe('status API', () => {
        it('has getStatus method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getStatus).toBe('function');
        });

        it('initial status is loading', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.getStatus()).toBe(Status.LOADING);
        });

        it('dispatches statuschange event when status changes', async () => {
            const element = createComponent();
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('statuschange', handler);

            // Emit data to trigger status change to VALID
            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                workItems: [],
                statusOptions: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
            const eventDetail = handler.mock.calls[0][0].detail;
            expect(eventDetail.oldValue).toBe(Status.LOADING);
            expect(eventDetail.value).toBe(Status.VALID);
        });
    });

    describe('project API', () => {
        it('has getProject method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getProject).toBe('function');
        });

        it('getProject returns null before data loads', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.getProject()).toBeNull();
        });

        it('getProject returns project data after load', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                projectStatus: 'Active',
                workItems: [],
                statusOptions: []
            });
            await flushPromises();

            const project = element.getProject();
            expect(project).toBeDefined();
            expect(project.projectId).toBe('proj-001');
            expect(project.projectName).toBe('Test Project');
        });

        it('has getProjectField method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getProjectField).toBe('function');
        });

        it('getProjectField returns specific field value', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                projectStatus: 'Active',
                workItems: [],
                statusOptions: []
            });
            await flushPromises();

            expect(element.getProjectField('projectName')).toBe('Test Project');
            expect(element.getProjectField('projectStatus')).toBe('Active');
        });

        it('dispatches projectchange event when project loads', async () => {
            const element = createComponent();
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('projectchange', handler);

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                workItems: [],
                statusOptions: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
            const eventDetail = handler.mock.calls[0][0].detail;
            expect(eventDetail.value.projectName).toBe('Test Project');
        });
    });

    describe('work items API', () => {
        const mockWorkItems = [
            {
                id: 'wi-001',
                name: 'Task 1',
                status: 'Not Started',
                children: [
                    { id: 'wi-002', name: 'Subtask 1', status: 'In Progress', children: [] }
                ]
            }
        ];

        it('has getWorkItems method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getWorkItems).toBe('function');
        });

        it('getWorkItems returns empty array before data loads', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.getWorkItems()).toEqual([]);
        });

        it('getWorkItems returns hierarchical data after load', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            const workItems = element.getWorkItems();
            expect(workItems).toHaveLength(1);
            expect(workItems[0].id).toBe('wi-001');
            expect(workItems[0].children).toHaveLength(1);
        });

        it('getWorkItems with parentId returns children', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            const children = element.getWorkItems('wi-001');
            expect(children).toHaveLength(1);
            expect(children[0].id).toBe('wi-002');
        });

        it('has getWorkItem method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getWorkItem).toBe('function');
        });

        it('getWorkItem returns specific work item by ID', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            const workItem = element.getWorkItem('wi-001');
            expect(workItem).toBeDefined();
            expect(workItem.id).toBe('wi-001');
            expect(workItem.name).toBe('Task 1');
        });

        it('getWorkItem finds nested work items', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            const workItem = element.getWorkItem('wi-002');
            expect(workItem).toBeDefined();
            expect(workItem.id).toBe('wi-002');
            expect(workItem.name).toBe('Subtask 1');
        });

        it('getWorkItem returns null for non-existent ID', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            expect(element.getWorkItem('non-existent')).toBeNull();
        });

        it('has getWorkItemField method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getWorkItemField).toBe('function');
        });

        it('getWorkItemField returns specific field value', async () => {
            const element = createComponent();
            await flushPromises();

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: mockWorkItems,
                statusOptions: []
            });
            await flushPromises();

            expect(element.getWorkItemField('wi-001', 'name')).toBe('Task 1');
            expect(element.getWorkItemField('wi-001', 'status')).toBe('Not Started');
        });
    });

    describe('setter methods', () => {
        it('has setWorkItem method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.setWorkItem).toBe('function');
        });

        it('has setWorkItemField method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.setWorkItemField).toBe('function');
        });

        it('has setWorkItemParent method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.setWorkItemParent).toBe('function');
        });

        it('setWorkItem calls updateWorkItem Apex', async () => {
            const element = createComponent();
            await flushPromises();

            // Load initial data
            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                workItems: [{ id: 'wi-001', name: 'Task 1', status: 'Not Started', children: [] }],
                statusOptions: []
            });
            await flushPromises();

            // Update work item
            await element.setWorkItem('wi-001', { status: 'Complete' });

            expect(updateWorkItem).toHaveBeenCalledWith({
                workItemId: 'wi-001',
                fields: { Status__c: 'Complete' }
            });
        });
    });

    describe('persistence API', () => {
        it('has save method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.save).toBe('function');
        });

        it('has reload method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.reload).toBe('function');
        });
    });

    describe('workitemsload event', () => {
        it('dispatches workitemsload event when data loads', async () => {
            const element = createComponent();
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                workItems: [{ id: 'wi-001', name: 'Task 1', children: [] }],
                statusOptions: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
            const eventDetail = handler.mock.calls[0][0].detail;
            expect(eventDetail.workItems).toHaveLength(1);
            expect(eventDetail.project).toBeDefined();
        });
    });

    describe('context detection', () => {
        it('detects project page from objectApiName', async () => {
            const element = createComponent({
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });

        it('detects work item page from objectApiName', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });
    });

    describe('work item page context', () => {
        it('handles work item wire data on work item page', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            getWorkItemWithChildren.emit({
                id: 'wi-001',
                name: 'Parent Task',
                children: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
        });

        it('handles wire error gracefully', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            const statusHandler = jest.fn();
            element.addEventListener('statuschange', statusHandler);

            getWorkItemWithChildren.error({ message: 'Work item not found' });
            await flushPromises();

            // Should set status to ERROR
            const lastCall = statusHandler.mock.calls[statusHandler.mock.calls.length - 1];
            expect(lastCall[0].detail.value).toBe(Status.ERROR);
        });
    });

    describe('module-level cache', () => {
        it('clearCache can be called without errors', () => {
            expect(() => clearCache()).not.toThrow();
        });

        it('data is shared between instances with same context', async () => {
            // Create first instance
            const element1 = createComponent({ recordId: 'proj-001' });
            await flushPromises();

