        });
    });

    describe('workitemsload event', () => {
        it('dispatches workitemsload event when data loads', async () => {
            const element = createComponent();
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                workItems: [{ id: 'wi-001', name: 'Task 1', children: [] }],
                statusOptions: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
            const eventDetail = handler.mock.calls[0][0].detail;
            expect(eventDetail.workItems).toHaveLength(1);
            expect(eventDetail.project).toBeDefined();
        });
    });

    describe('context detection', () => {
        it('detects project page from objectApiName', async () => {
            const element = createComponent({
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });

        it('detects work item page from objectApiName', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });
    });

    describe('work item page context', () => {
        it('handles work item wire data on work item page', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            const handler = jest.fn();
            element.addEventListener('workitemsload', handler);

            getWorkItemWithChildren.emit({
                id: 'wi-001',
                name: 'Parent Task',
                children: []
            });
            await flushPromises();

            expect(handler).toHaveBeenCalled();
        });

        it('handles wire error gracefully', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            const statusHandler = jest.fn();
            element.addEventListener('statuschange', statusHandler);

            getWorkItemWithChildren.error({ message: 'Work item not found' });
            await flushPromises();

            // Should set status to ERROR
            const lastCall = statusHandler.mock.calls[statusHandler.mock.calls.length - 1];
            expect(lastCall[0].detail.value).toBe(Status.ERROR);
        });
    });

    describe('module-level cache', () => {
        it('clearCache can be called without errors', () => {
            expect(() => clearCache()).not.toThrow();
        });

        it('data is shared between instances with same context', async () => {
            // Create first instance
            const element1 = createComponent({ recordId: 'proj-001' });
            await flushPromises();

            // Load data
            getWorkItemsForProject.emit({
                projectId: 'proj-001',
                projectName: 'Test Project',
                workItems: [{ id: 'wi-001', name: 'Task 1', children: [] }],
                statusOptions: []
            });
            await flushPromises();

            // Create second instance with same recordId
            const element2 = createComponent({ recordId: 'proj-001' });
            await flushPromises();

            // Second instance should have the cached data immediately
            const workItems = element2.getWorkItems();
            expect(workItems).toHaveLength(1);
            expect(workItems[0].name).toBe('Task 1');
        });
    });
});

